const clamp=q=>Math.max(0,Math.min(1,q));
export const defaultRoutes=[
 {id:'north',name:'Up through town',points:[[.5,.54],[.51,.43],[.53,.3],[.52,.15]],delay:0,duration:4.1},
 {id:'west',name:'Left branch',points:[[.5,.54],[.44,.5],[.35,.45],[.25,.35]],delay:.45,duration:4.5},
 {id:'east',name:'Right branch',points:[[.5,.54],[.57,.49],[.68,.48],[.78,.42]],delay:.8,duration:4.3},
 {id:'south',name:'Down through town',points:[[.5,.54],[.47,.64],[.43,.74],[.32,.85]],delay:1.1,duration:4.4},
 {id:'northeast',name:'Upper fork',points:[[.5,.54],[.55,.43],[.66,.33],[.7,.2]],delay:1.5,duration:4.3}
];
export function routeSamples(points,count=120){if(!Array.isArray(points)||points.length<2)return [[.5,.5],[.5,.5]];const out=[];for(let i=0;i<points.length-1;i++){const a=points[Math.max(0,i-1)],b=points[i],c=points[i+1],d=points[Math.min(points.length-1,i+2)];for(let j=0;j<count/(points.length-1);j++){const t=j/Math.ceil(count/(points.length-1));out.push([0,1].map(k=>.5*(2*b[k]+(-a[k]+c[k])*t+(2*a[k]-5*b[k]+4*c[k]-d[k])*t*t+(-a[k]+3*b[k]-3*c[k]+d[k])*t*t*t)))}}out.push(points.at(-1));return out}
export function routePoint(points,progress){const sample=routeSamples(points),lengths=sample.slice(1).map((p,i)=>Math.hypot(p[0]-sample[i][0],p[1]-sample[i][1])),total=lengths.reduce((s,v)=>s+v,0);let remaining=clamp(progress)*total;for(let i=0;i<lengths.length;i++){if(remaining<=lengths[i]){const q=lengths[i]?remaining/lengths[i]:0;return sample[i].map((v,k)=>v+(sample[i+1][k]-v)*q)}remaining-=lengths[i]}return sample.at(-1)}
export function routeState(route,age,options={}){const q=clamp((age-(route.delay||0))/Math.max(.05,route.duration||4)),p=routePoint(route.points,q),start=route.startSize??options.startSize??52,end=route.endSize??options.endSize??25;return {q,point:p,width:start+(end-start)*q,opacity:clamp((age-(route.delay||0))/.18),visible:route.enabled!==false&&age>=(route.delay||0)}}
export function paintRouteLine(c,points,progress,{width=960,height=540,color='#70c8ed',thickness=2,style='dashed',dash=6,gap=5,opacity=.75}={}){if(progress<=0||thickness<=0)return;c.save();c.globalAlpha*=opacity;c.strokeStyle=color;c.lineWidth=thickness;c.lineCap='round';c.setLineDash(style==='solid'?[]:style==='dotted'?[1,gap]:[dash,gap]);const samples=routeSamples(points),lengths=samples.slice(1).map((p,i)=>Math.hypot(p[0]-samples[i][0],p[1]-samples[i][1]));let remaining=lengths.reduce((sum,v)=>sum+v,0)*clamp(progress);c.beginPath();c.moveTo(samples[0][0]*width,samples[0][1]*height);for(let i=0;i<lengths.length&&remaining>0;i++){const q=lengths[i]?Math.min(1,remaining/lengths[i]):0;c.lineTo((samples[i][0]+(samples[i+1][0]-samples[i][0])*q)*width,(samples[i][1]+(samples[i+1][1]-samples[i][1])*q)*height);remaining-=lengths[i]}c.stroke();c.restore()}
